recipes.code:
{
  "inputs": [
    {
      "id": "formpaste-token",
      "type": "promptString",
      "description": "Formpaste API token starting with fpat_, minted in the dashboard under Settings -> API & MCP. Use a setup-scoped token unless the agent needs to read submission content.",
      "password": true
    }
  ],
  "servers": {
    "formpaste": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "formpaste-mcp@1.0.1"
      ],
      "env": {
        "FORMPASTE_TOKEN": "${input:formpaste-token}"
      }
    }
  }
}
